package com.telusko.placement_portal.service;

import com.telusko.placement_portal.dto.*;
import com.telusko.placement_portal.entity.*;
import com.telusko.placement_portal.entity.AptitudeAttempt.*;
import com.telusko.placement_portal.entity.AptitudeQuestion.*;
import com.telusko.placement_portal.repository.*;
import com.telusko.placement_portal.security.UserPrincipal;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class AptitudeService {
    private final AptitudeQuestionRepository questions;
    private final AptitudeAttemptRepository attempts;
    private final AptitudeAttemptQuestionRepository attemptQuestions;
    private final StudentService studentService;
    public AptitudeService(AptitudeQuestionRepository q, AptitudeAttemptRepository a, AptitudeAttemptQuestionRepository aq, StudentService studentService) { questions=q; attempts=a; attemptQuestions=aq; this.studentService=studentService; }

    @Transactional(readOnly=true)
    public List<AptitudeCatalogCategoryDto> catalog() {
        List<AptitudeQuestion> all=questions.findAllByActiveTrue();
        return Arrays.stream(Category.values()).map(c -> new AptitudeCatalogCategoryDto(c,label(c),all.stream().filter(q->q.getCategory()==c).count(),Arrays.stream(Topic.values()).filter(t->categoryFor(t)==c).map(t->new AptitudeCatalogTopicDto(t,label(t),all.stream().filter(q->q.getTopic()==t).count())).toList())).toList();
    }
    private Category categoryFor(Topic t) { if(t.ordinal()<=Topic.DATA_INTERPRETATION.ordinal())return Category.QUANTITATIVE_APTITUDE; if(t.ordinal()<=Topic.RANKING_AND_ORDERING.ordinal())return Category.LOGICAL_REASONING; if(t.ordinal()<=Topic.PARA_JUMBLES.ordinal())return Category.VERBAL_ABILITY; return Category.COMPUTER_APTITUDE; }
    private String label(Enum<?> e) { String s=e.name().toLowerCase(Locale.ROOT).replace('_',' '); return Arrays.stream(s.split(" ")).map(w->w.isEmpty()?w:Character.toUpperCase(w.charAt(0))+w.substring(1)).collect(Collectors.joining(" ")); }
    @Transactional
    public AptitudeSessionDto start(UserPrincipal principal,AptitudeStartRequest req) {
        expire(principal.getId());
        if(attempts.findFirstByStudent_IdAndStatusOrderByStartedAtDesc(principal.getId(),Status.ACTIVE).isPresent()) throw new ResponseStatusException(HttpStatus.CONFLICT,"An active aptitude session already exists. Resume it first.");
        if(req.topic()!=null && req.category()!=null && categoryFor(req.topic())!=req.category()) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Topic does not belong to the selected category.");
        List<AptitudeQuestion> pool=questions.findAllByActiveTrue().stream().filter(q->req.category()==null||q.getCategory()==req.category()).filter(q->req.topic()==null||q.getTopic()==req.topic()).filter(q->req.difficulty()==null||q.getDifficulty()==req.difficulty()).collect(Collectors.toCollection(ArrayList::new));
        if(pool.size()<req.questionCount()) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only "+pool.size()+" matching questions are available.");
        Collections.shuffle(pool); Student st=studentService.getOrCreateProfile(principal);
        AptitudeAttempt a=new AptitudeAttempt(); a.setStudent(st); a.setMode(req.mode()); a.setCategory(req.category()!=null?req.category():req.topic()!=null?categoryFor(req.topic()):null); a.setTopic(req.topic()); a.setDifficulty(req.difficulty()); a.setQuestionCount(req.questionCount());
        if(req.mode()==Mode.TIMED_TEST){if(req.durationSeconds()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Timed tests require a duration."); a.setDurationSeconds(req.durationSeconds()); a.setExpiresAt(LocalDateTime.now().plusSeconds(req.durationSeconds()));}
        attempts.save(a); List<AptitudeAttemptQuestion> rows=new ArrayList<>();
        for(int i=0;i<req.questionCount();i++){var row=new AptitudeAttemptQuestion();row.setAttempt(a);row.setQuestion(pool.get(i));row.setPosition(i);List<Integer> order=new ArrayList<>(List.of(0,1,2,3));Collections.shuffle(order);row.setOptionOrder(order.stream().map(String::valueOf).collect(Collectors.joining(",")));rows.add(row);} attemptQuestions.saveAll(rows); return session(a,rows);
    }
    @Transactional
    public Optional<AptitudeSessionDto> active(UserPrincipal p) { expire(p.getId()); return attempts.findFirstByStudent_IdAndStatusOrderByStartedAtDesc(p.getId(),Status.ACTIVE).map(a->session(a,attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(a.getId()))); }
    @Transactional(noRollbackFor = ResponseStatusException.class)
    public AptitudeSessionDto session(UserPrincipal p,long id) { AptitudeAttempt a=owned(p,id); if(expired(a)){finish(a,Status.TIME_EXPIRED);throw new ResponseStatusException(HttpStatus.GONE,"Session expired; result is available in attempt history.");} return session(a,attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(id)); }
    private AptitudeSessionDto session(AptitudeAttempt a,List<AptitudeAttemptQuestion> rows) { return new AptitudeSessionDto(a.getId(),a.getMode(),a.getStatus(),a.getCategory(),a.getTopic(),a.getDifficulty(),a.getQuestionCount(),(int)rows.stream().filter(r->r.getSelectedOptionIndex()!=null).count(),a.getStartedAt(),a.getExpiresAt(),rows.stream().map(this::questionDto).toList()); }
    private AptitudeQuestionDto questionDto(AptitudeAttemptQuestion r) { List<Integer> order=order(r); return new AptitudeQuestionDto(r.getId(),r.getPosition(),r.getQuestion().getQuestionText(),r.getQuestion().getCategory(),r.getQuestion().getTopic(),r.getQuestion().getDifficulty(),order.stream().map(i->new AptitudeOptionDto(order.indexOf(i),r.getQuestion().optionAt(i))).toList(),r.getSelectedOptionIndex(),r.isMarkedForReview()); }
    @Transactional
    public AptitudeAnswerResultDto answer(UserPrincipal p,long id,long aqId,AptitudeAnswerRequest req) { AptitudeAttempt a=owned(p,id); if(a.getStatus()!=Status.ACTIVE)return new AptitudeAnswerResultDto(true,null,null,null,null,null); if(expired(a)){finish(a,Status.TIME_EXPIRED);return new AptitudeAnswerResultDto(true,null,null,null,null,null);} AptitudeAttemptQuestion r=attemptQuestions.findByIdAndAttempt_Id(aqId,id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)); r.setSelectedOptionIndex(req.selectedOptionIndex()); r.setMarkedForReview(req.markedForReview()); if(a.getMode()==Mode.PRACTICE&&req.selectedOptionIndex()!=null){int correct=order(r).indexOf(r.getQuestion().getCorrectOptionIndex());return new AptitudeAnswerResultDto(false,req.selectedOptionIndex(),correct,r.getQuestion().optionAt(r.getQuestion().getCorrectOptionIndex()),r.getQuestion().getExplanation(),req.selectedOptionIndex()==correct);} return new AptitudeAnswerResultDto(false,req.selectedOptionIndex(),null,null,null,null); }
    @Transactional
    public AptitudeResultDto submit(UserPrincipal p,long id) { AptitudeAttempt a=owned(p,id); if(a.getStatus()==Status.ACTIVE)finish(a,expired(a)?Status.TIME_EXPIRED:Status.COMPLETED); return result(a,attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(id)); }
    private boolean expired(AptitudeAttempt a){return a.getMode()==Mode.TIMED_TEST&&a.getExpiresAt()!=null&&!a.getExpiresAt().isAfter(LocalDateTime.now());}
    private void expire(Long studentId){attempts.findFirstByStudent_IdAndStatusOrderByStartedAtDesc(studentId,Status.ACTIVE).filter(this::expired).ifPresent(a->finish(a,Status.TIME_EXPIRED));}
    @Transactional public void expireOverdue(){attempts.findAllByStatusAndExpiresAtLessThanEqual(Status.ACTIVE,LocalDateTime.now()).forEach(a->finish(a,Status.TIME_EXPIRED));}
    private void finish(AptitudeAttempt a,Status status){List<AptitudeAttemptQuestion> rows=attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(a.getId());int total=rows.size(),answered=(int)rows.stream().filter(r->r.getSelectedOptionIndex()!=null).count(),correct=(int)rows.stream().filter(this::isCorrect).count();LocalDateTime now=LocalDateTime.now();a.setStatus(status);a.setSubmittedAt(now);a.setCorrectCount(correct);a.setIncorrectCount(answered-correct);a.setUnansweredCount(total-answered);a.setScorePercentage(pct(correct,total));a.setAccuracyPercentage(pct(correct,answered));int elapsed=(int)Math.max(0,Duration.between(a.getStartedAt(),now).getSeconds());if(a.getDurationSeconds()!=null)elapsed=Math.min(elapsed,a.getDurationSeconds());a.setTimeTakenSeconds(elapsed);}
    private boolean isCorrect(AptitudeAttemptQuestion r){return r.getSelectedOptionIndex()!=null&&order(r).get(r.getSelectedOptionIndex())==r.getQuestion().getCorrectOptionIndex();}
    private List<Integer> order(AptitudeAttemptQuestion r){return Arrays.stream(r.getOptionOrder().split(",")).map(Integer::parseInt).toList();}
    private int pct(int n,int d){return d==0?0:(int)Math.round(n*100.0/d);}
    private AptitudeAttempt owned(UserPrincipal p,long id){AptitudeAttempt a=attempts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!a.getStudent().getId().equals(p.getId()))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return a;}
    @Transactional(readOnly=true) public AptitudeResultDto getResult(UserPrincipal p,long id){AptitudeAttempt a=owned(p,id);if(a.getStatus()==Status.ACTIVE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Submit the active session to view its result.");return result(a,attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(id));}
    private AptitudeResultDto result(AptitudeAttempt a,List<AptitudeAttemptQuestion> rows){Map<String,int[]> cats=new LinkedHashMap<>(),topics=new LinkedHashMap<>(),diffs=new LinkedHashMap<>();for(var r:rows){acc(cats,r.getQuestion().getCategory().name(),r);acc(topics,r.getQuestion().getTopic().name(),r);acc(diffs,r.getQuestion().getDifficulty().name(),r);}return new AptitudeResultDto(a.getId(),a.getMode(),a.getStatus(),a.getCategory(),a.getTopic(),a.getDifficulty(),a.getStartedAt(),a.getSubmittedAt(),rows.size(),nz(a.getCorrectCount()),nz(a.getIncorrectCount()),nz(a.getUnansweredCount()),nz(a.getScorePercentage()),nz(a.getAccuracyPercentage()),nz(a.getTimeTakenSeconds()),performance(cats),performance(topics),performance(diffs),rows.stream().map(this::review).toList());}
    private void acc(Map<String,int[]> m,String key,AptitudeAttemptQuestion r){int[] x=m.computeIfAbsent(key,k->new int[3]);x[0]++;if(r.getSelectedOptionIndex()!=null){x[1]++;if(isCorrect(r))x[2]++;}}
    private List<AptitudePerformanceDto> performance(Map<String,int[]> m){return m.entrySet().stream().map(e->{int[]x=e.getValue();return new AptitudePerformanceDto(e.getKey(),labelKey(e.getKey()),x[0],x[1],x[2],x[1]-x[2],x[0]-x[1],pct(x[2],x[1]),pct(x[2],x[0]));}).toList();}
    private String labelKey(String key){String s=key.toLowerCase(Locale.ROOT).replace('_',' ');return Arrays.stream(s.split(" ")).map(w->Character.toUpperCase(w.charAt(0))+w.substring(1)).collect(Collectors.joining(" "));}
    private AptitudeQuestionReviewDto review(AptitudeAttemptQuestion r){int good=order(r).indexOf(r.getQuestion().getCorrectOptionIndex());return new AptitudeQuestionReviewDto(r.getId(),r.getPosition(),r.getQuestion().getQuestionText(),r.getQuestion().getCategory(),r.getQuestion().getTopic(),r.getQuestion().getDifficulty(),order(r).stream().map(i->new AptitudeOptionDto(order(r).indexOf(i),r.getQuestion().optionAt(i))).toList(),r.getSelectedOptionIndex(),good,r.getQuestion().getExplanation(),r.isMarkedForReview());}
    @Transactional(readOnly=true) public List<AptitudeHistoryItemDto> history(UserPrincipal p){return attempts.findAllByStudent_IdAndStatusInOrderByStartedAtDesc(p.getId(),List.of(Status.COMPLETED,Status.TIME_EXPIRED)).stream().map(a->new AptitudeHistoryItemDto(a.getId(),a.getMode(),a.getStatus(),a.getCategory(),a.getTopic(),a.getStartedAt(),a.getSubmittedAt(),a.getQuestionCount(),a.getScorePercentage(),a.getAccuracyPercentage(),a.getTimeTakenSeconds())).toList();}
    @Transactional(readOnly=true) public AptitudeAnalyticsDto analytics(UserPrincipal p){var done=attempts.findAllByStudent_IdAndStatusInOrderByStartedAtDesc(p.getId(),List.of(Status.COMPLETED,Status.TIME_EXPIRED));Map<String,int[]> tm=new LinkedHashMap<>(),cm=new LinkedHashMap<>(),dm=new LinkedHashMap<>();int ans=0,correct=0,topicCount=0;Set<Topic> covered=new HashSet<>();List<Integer> accs=new ArrayList<>();for(var a:done){List<AptitudeAttemptQuestion> rs=attemptQuestions.findAllByAttempt_IdOrderByPositionAsc(a.getId());for(var r:rs)if(r.getSelectedOptionIndex()!=null){ans++;covered.add(r.getQuestion().getTopic());acc(tm,r.getQuestion().getTopic().name(),r);acc(cm,r.getQuestion().getCategory().name(),r);acc(dm,r.getQuestion().getDifficulty().name(),r);if(isCorrect(r))correct++;}if(a.getAccuracyPercentage()!=null)accs.add(a.getAccuracyPercentage());}topicCount=covered.size();double mean=accs.stream().mapToInt(i->i).average().orElse(0);double sd=accs.size()<2?0:Math.sqrt(accs.stream().mapToDouble(i->Math.pow(i-mean,2)).average().orElse(0));Integer consistency=accs.size()<2?null:(int)Math.round(Math.max(0,100-sd));int coverage=pct(topicCount,Topic.values().length);Integer readiness=done.isEmpty()?null:(int)Math.round((pct(correct,ans)*.6)+(coverage*.2)+((consistency==null?pct(correct,ans):consistency)*.2));List<AptitudeTopicStatDto> stats=tm.entrySet().stream().map(e->{int[]x=e.getValue();int n=x[1];int ac=pct(x[2],n);return new AptitudeTopicStatDto(categoryFor(Topic.valueOf(e.getKey())),Topic.valueOf(e.getKey()),n,x[2],ac,n>=5&&ac<60,n>=5&&ac>=80);}).toList();var weak=stats.stream().filter(AptitudeTopicStatDto::weak).toList();var strong=stats.stream().filter(AptitudeTopicStatDto::strong).toList();var recent=done.stream().limit(8).map(a->new AptitudeHistoryItemDto(a.getId(),a.getMode(),a.getStatus(),a.getCategory(),a.getTopic(),a.getStartedAt(),a.getSubmittedAt(),a.getQuestionCount(),a.getScorePercentage(),a.getAccuracyPercentage(),a.getTimeTakenSeconds())).toList();return new AptitudeAnalyticsDto(done.size(),ans,correct,pct(correct,ans),(int)Math.round(done.stream().mapToInt(a->nz(a.getScorePercentage())).average().orElse(0)),done.isEmpty()?null:done.get(0).getScorePercentage(),done.isEmpty()?null:done.get(0).getAccuracyPercentage(),done.isEmpty()?null:done.get(0).getSubmittedAt(),readiness,readiness==null?"No submitted aptitude attempts yet.":"60% accuracy, 20% topic coverage, and 20% consistency; consistency uses all saved attempt accuracies when at least two attempts exist.",consistency,coverage,topicCount,Topic.values().length,5,weak,strong,stats,performance(cm),performance(dm),recent);}
    private int nz(Integer i){return i==null?0:i;}
}
